import * as vendorModule from '../../vendor/stk-gov/stk-gov-parametros.js?v=20261119-1304';

/**
 * Infrastructure / src/infrastructure/VendorParameters.js
 * Adapter of the ParametersPort over the common parameter module generated by _design-system (ADR-001, D5).
 *
 * Port (used by the application layer):
 *   validity(id, date) → the validity in force on the date, or undefined
 *   value(id, date)    → its value, or undefined
 *   input(id, date)    → { id, valor, tipo, status, periodo }, the shape of Resultado.insumos
 *   seal(inputs, exactFormula) → 'exato' | 'estimativa'
 * Without a date, today's date is used. Legal parameters are read on the date of the period being computed (RN-M01).
 */
export class VendorParameters {
  /** @param {Object} [source] Parameter module (injectable in tests) */
  constructor(source = vendorModule) {
    this.source = source;
  }

  validity(id, date = new Date()) { return this.source.vigencia(id, date); }

  value(id, date = new Date()) { return this.source.valor(id, date); }

  input(id, date = new Date()) { return this.source.insumo(id, date); }

  seal(inputs, exactFormula = true) { return this.source.selo(inputs, exactFormula); }
}
